-- Atlas V103: trust, commerce, connector and contractor-workspace persistence targets
BEGIN;
CREATE TABLE IF NOT EXISTS atlas_connector_grants (tenant_id TEXT NOT NULL, grant_id TEXT NOT NULL, connector_id TEXT NOT NULL, principal_id TEXT NOT NULL, allowed_operations JSONB NOT NULL, allowed_scopes JSONB NOT NULL, expires_at TIMESTAMPTZ NOT NULL, environment TEXT NOT NULL CHECK (environment IN ('sandbox','staging','production')), checksum CHAR(64) NOT NULL, PRIMARY KEY (tenant_id, grant_id));
ALTER TABLE atlas_connector_grants ENABLE ROW LEVEL SECURITY; ALTER TABLE atlas_connector_grants FORCE ROW LEVEL SECURITY;
CREATE POLICY atlas_connector_grants_tenant ON atlas_connector_grants USING (tenant_id = nullif(current_setting('app.tenant_id', true),'')) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id', true),''));
CREATE TABLE IF NOT EXISTS atlas_automation_runs (tenant_id TEXT NOT NULL, run_id TEXT NOT NULL, automation_id TEXT NOT NULL, status TEXT NOT NULL CHECK (status IN ('planned','running','completed','failed','dead_letter','needs_approval')), idempotency_key TEXT NOT NULL, execution_key CHAR(64) NOT NULL, records_processed INTEGER NOT NULL DEFAULT 0, records_failed INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL, finished_at TIMESTAMPTZ, PRIMARY KEY (tenant_id, run_id), UNIQUE (tenant_id, idempotency_key));
ALTER TABLE atlas_automation_runs ENABLE ROW LEVEL SECURITY; ALTER TABLE atlas_automation_runs FORCE ROW LEVEL SECURITY;
CREATE POLICY atlas_automation_runs_tenant ON atlas_automation_runs USING (tenant_id = nullif(current_setting('app.tenant_id', true),'')) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id', true),''));
CREATE TABLE IF NOT EXISTS atlas_billing_ledger (tenant_id TEXT NOT NULL, transaction_id TEXT NOT NULL, currency CHAR(3) NOT NULL, source_ref TEXT NOT NULL, idempotency_key TEXT NOT NULL, entries JSONB NOT NULL, status TEXT NOT NULL CHECK (status IN ('posted','voided','pending')), checksum CHAR(64) NOT NULL, posted_at TIMESTAMPTZ NOT NULL, PRIMARY KEY (tenant_id, transaction_id), UNIQUE (tenant_id, idempotency_key));
ALTER TABLE atlas_billing_ledger ENABLE ROW LEVEL SECURITY; ALTER TABLE atlas_billing_ledger FORCE ROW LEVEL SECURITY;
CREATE POLICY atlas_billing_ledger_tenant ON atlas_billing_ledger USING (tenant_id = nullif(current_setting('app.tenant_id', true),'')) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id', true),''));
REVOKE UPDATE, DELETE, TRUNCATE ON atlas_billing_ledger FROM PUBLIC;
CREATE TABLE IF NOT EXISTS atlas_spend_decisions (tenant_id TEXT NOT NULL, decision_id TEXT NOT NULL, policy_checksum CHAR(64) NOT NULL, amount NUMERIC(20,4) NOT NULL CHECK (amount > 0), currency CHAR(3) NOT NULL, category TEXT NOT NULL, decision TEXT NOT NULL CHECK (decision IN ('allowed','denied','needs_approval')), idempotency_key TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL, PRIMARY KEY (tenant_id, decision_id), UNIQUE (tenant_id, idempotency_key));
ALTER TABLE atlas_spend_decisions ENABLE ROW LEVEL SECURITY; ALTER TABLE atlas_spend_decisions FORCE ROW LEVEL SECURITY;
CREATE POLICY atlas_spend_decisions_tenant ON atlas_spend_decisions USING (tenant_id = nullif(current_setting('app.tenant_id', true),'')) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id', true),''));
CREATE TABLE IF NOT EXISTS atlas_freelancer_workspaces (tenant_id TEXT NOT NULL, workspace_id TEXT NOT NULL, project_id TEXT NOT NULL, budget NUMERIC(20,4) NOT NULL CHECK (budget > 0), currency CHAR(3) NOT NULL, payment_mode TEXT NOT NULL, snapshot JSONB NOT NULL, checksum CHAR(64) NOT NULL, created_at TIMESTAMPTZ NOT NULL, PRIMARY KEY (tenant_id, workspace_id));
ALTER TABLE atlas_freelancer_workspaces ENABLE ROW LEVEL SECURITY; ALTER TABLE atlas_freelancer_workspaces FORCE ROW LEVEL SECURITY;
CREATE POLICY atlas_freelancer_workspaces_tenant ON atlas_freelancer_workspaces USING (tenant_id = nullif(current_setting('app.tenant_id', true),'')) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id', true),''));
CREATE TABLE IF NOT EXISTS atlas_security_events (tenant_id TEXT NOT NULL, event_id TEXT NOT NULL, actor_id TEXT, action TEXT NOT NULL, outcome TEXT NOT NULL, risk_score INTEGER CHECK (risk_score BETWEEN 0 AND 100), metadata JSONB NOT NULL DEFAULT '{}'::jsonb, occurred_at TIMESTAMPTZ NOT NULL, PRIMARY KEY (tenant_id, event_id));
ALTER TABLE atlas_security_events ENABLE ROW LEVEL SECURITY; ALTER TABLE atlas_security_events FORCE ROW LEVEL SECURITY;
CREATE POLICY atlas_security_events_tenant ON atlas_security_events USING (tenant_id = nullif(current_setting('app.tenant_id', true),'')) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id', true),''));
REVOKE UPDATE, DELETE, TRUNCATE ON atlas_security_events FROM PUBLIC;
COMMIT;